solution:
fn main() -> Int {
  let temperature = 35;
  let feel = match temperature {
    t if t < 0 => "freezing",
    t if t < 20 => "cold",
    t if t < 30 => "warm",
    _ => "hot",
  };
  io.println(feel);
  return 0;
}
